mapper.select:
select idproducto, idproductosin, idgrupo, idunidadmedida, producto, cantidadcaja, preciounitario, enlaceproducto, habilitado, codigocorto
from facturacion.productos
where idproducto=#{id}

select idproducto, idproductosin, idgrupo, idunidadmedida, producto, cantidadcaja, preciounitario, enlaceproducto, habilitado, codigocorto
from facturacion.productos
where habilitado and idgrupo=#{idgrupo}
order by producto
limit #{cantidad} offset #{pagina}

select count(idproducto)
from facturacion.productos
where habilitado and idgrupo=#{idgrupo}

select idproducto, idproductosin, idgrupo, idunidadmedida, producto, cantidadcaja, preciounitario, enlaceproducto, habilitado, codigocorto
from facturacion.productos
where habilitado and codigocorto=#{codigocorto}
